create table if not exists public.goodies_contact_numbers (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade, phone_number text not null, label text not null default '', created_at timestamptz not null default now(), unique(user_id,phone_number)); alter table public.goodies_contact_numbers enable row level security; grant select,insert,update,delete on public.goodies_contact_numbers to authenticated; create policy "goodies_numbers_owner_select" on public.goodies_contact_numbers for select to authenticated using (user_id=(select auth.uid())); create policy "goodies_numbers_owner_insert" on public.goodies_contact_numbers for insert to authenticated with check (user_id=(select auth.uid())); create policy "goodies_numbers_owner_update" on public.goodies_contact_numbers for update to authenticated using (user_id=(select auth.uid())) with check (user_id=(select auth.uid())); create policy "goodies_numbers_owner_delete" on public.goodies_contact_numbers for delete to authenticated using (user_id=(select auth.uid()));
